use infinite_core::*;use std::num::NonZeroU32;
fn n(v:u32)->NonZeroU32{NonZeroU32::new(v).unwrap()}
fn view()->ViewRect{ViewRect{min:GridPosition{x:-100,y:-100},max:GridPosition{x:100,y:100}}}
fn setup()->(World,[EntityId;2],CombatFrame,ComponentFrame,CombatConnections,ConnectionId){
 let mut w=World::default();let a=w.spawn(GridPosition::default()).unwrap();let b=w.spawn(GridPosition{x:16,y:0}).unwrap();for e in[a,b]{w.configure_health(e,100,n(100)).unwrap();}w.define_public_component(1,b"model").unwrap();let mut net=CombatConnections::with_window(10,NetworkConfig{connections:3,retry_ms:10,ack_timeout_ms:100,blocked_timeout_ms:100,combat:CombatSyncConfig{pending_events:64,events_per_packet:1},..NetworkConfig::default()},4).unwrap();let id=net.connect().unwrap();net.set_motion_view(id,view()).unwrap();net.set_component_view(id,Some(a),view()).unwrap();(w,[a,b],CombatFrame::new(n(32)),ComponentFrame::new(n(32)),net,id)
}
fn capture(w:&mut World,e:[EntityId;2],c:&mut CombatFrame,f:&mut ComponentFrame,net:&mut CombatConnections,id:ConnectionId){
 w.advance_tick().unwrap();w.set_position(e[0],GridPosition{x:w.tick().0 as i32,y:0}).unwrap();let health=w.apply_damage(e[1],1).unwrap().health;let mut fields=ComponentFields::from_words(&[1,w.tick().0 as u32]).unwrap();fields.set_reference(0,1).unwrap();w.set_component(e[0],ComponentRecord{key:ComponentKey{kind:ComponentKind::Appearance,instance:0},scope:ComponentScope::Nearby,fields}).unwrap();
 c.capture(w,&[CombatEvent{attacker:e[0],target:e[1],kind:CombatEventKind::Hit{health,next_ready:Tick(w.tick().0+1)}}]).unwrap();f.capture(w).unwrap();net.observe(id,c,view()).unwrap();
}
fn poll(net:&mut CombatConnections,f:&ComponentFrame,now:u64,limit:usize,bytes:&mut Vec<u8>)->Vec<Vec<u8>>{
 let mut budget=NetworkBudget{work:1,bytes:limit};let mut notices=Vec::new();let r=net.poll_with_components(now,f,&mut budget,&mut notices,|_,p|{let count=p.len().min(3);bytes.extend_from_slice(&p[..count]);WriteProgress::Written(count)}).unwrap();assert_eq!(r.bytes+budget.bytes,limit);assert_eq!(r.visited+budget.work,1);assert!(notices.is_empty());let mut packets=Vec::new();while bytes.len()>=4{let size=u32::from_le_bytes(bytes[..4].try_into().unwrap())as usize;assert!(size<=MAX_COMPONENT_PACKET_BYTES.max(MAX_COMBAT_SYNC_PACKET_BYTES));if bytes.len()<size+4{break;}packets.push(bytes[4..4+size].to_vec());bytes.drain(..4+size);}packets
}
struct Client{motion:Replica,combat:CombatReplica,components:ComponentReplica,events:Vec<CombatFeedback>}
impl Client{fn new(stream:u64)->Self{Self{motion:Replica::new(stream),combat:CombatReplica::new_windowed(stream),components:ComponentReplica::new_with_definitions(stream),events:Vec::new()}}fn apply(&mut self,p:&[u8])->[u8;20]{match &p[..2]{b"IS"=>self.motion.apply(p).unwrap().acknowledgement(),b"IP"=>self.components.apply(p).unwrap().acknowledgement(),b"IC"=>{let r=self.combat.apply(p).unwrap();self.events.extend(self.combat.drain_feedback());r.acknowledgement()},_=>panic!("interleaved frame")}}}
fn drained(net:&CombatConnections,id:ConnectionId,f:&ComponentFrame)->bool{let c=net.status(id).unwrap();let m=net.motion_status(id).unwrap().unwrap();let p=net.component_status(id).unwrap().unwrap();c.pending_bytes==0&&c.queued_events==0&&m.pending_bytes==0&&p.pending_bytes==0&&m.last_prepared_tick==f.tick()&&p.last_prepared_tick==f.tick()}
#[test]
fn one_byte_budget_keeps_three_channels_framed_fair_and_exact(){
 let(mut w,e,mut c,mut f,mut net,id)=setup();for _ in 0..8{capture(&mut w,e,&mut c,&mut f,&mut net,id);}let mut client=Client::new(10);let mut bytes=Vec::new();let mut kinds=Vec::new();for _ in 0..20000{for p in poll(&mut net,&f,0,1,&mut bytes){kinds.push(p[..2].to_vec());net.acknowledge(id,&client.apply(&p)).unwrap();}if drained(&net,id,&f){break;}}
 assert!(drained(&net,id,&f));assert!(bytes.is_empty());assert_eq!(&kinds[..3],&[b"IC".to_vec(),b"IS".to_vec(),b"IP".to_vec()]);assert_eq!(client.events.iter().map(|e|e.tick.0).collect::<Vec<_>>(),(1..=8).collect::<Vec<_>>());assert_eq!(client.combat.states().iter().find(|s|s.entity==e[1]).unwrap().health.unwrap().current,92);assert_eq!(client.motion.states(),f.motion_frame().visible(view()).unwrap());assert_eq!(client.components.states(),ComponentSelector::new(Some(e[0])).select(&f,view()).unwrap());assert_eq!(client.components.definition(1).unwrap().bytes.as_ref(),b"model");
}
#[test]
fn component_ack_wait_does_not_hold_ordered_combat_or_motion(){
 let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id);let mut client=Client::new(10);let(mut bytes,mut held)=(Vec::new(),None);for _ in 0..2000{for p in poll(&mut net,&f,0,64,&mut bytes){let ack=client.apply(&p);if p.starts_with(b"IP"){held=Some(ack);}else{net.acknowledge(id,&ack).unwrap();}}if held.is_some(){break;}}
 for _ in 0..5{capture(&mut w,e,&mut c,&mut f,&mut net,id);}w.define_public_component(1,b"updated").unwrap();capture(&mut w,e,&mut c,&mut f,&mut net,id);for _ in 0..4000{for p in poll(&mut net,&f,0,64,&mut bytes){assert!(!p.starts_with(b"IP"));net.acknowledge(id,&client.apply(&p)).unwrap();}if client.events.len()==7&&client.motion.states()[0].position.x==7{break;}}
 assert_eq!(client.events.len(),7);assert_eq!(client.components.states()[0].record.fields.get(1),Some(1));assert_eq!(client.components.definition(1).unwrap().bytes.as_ref(),b"model");net.acknowledge(id,&held.unwrap()).unwrap();for _ in 0..2000{for p in poll(&mut net,&f,0,64,&mut bytes){net.acknowledge(id,&client.apply(&p)).unwrap();}if drained(&net,id,&f){break;}}assert!(drained(&net,id,&f));assert_eq!(client.components.states()[0].record.fields.get(1),Some(7));assert_eq!(client.components.definition(1).unwrap().bytes.as_ref(),b"updated");
}
#[test]
fn component_ack_during_partial_retry_waits_for_exact_frame_end(){
 let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id);let mut client=Client::new(10);let(mut bytes,mut original,mut held)=(Vec::new(),Vec::new(),None);for _ in 0..3000{for p in poll(&mut net,&f,0,64,&mut bytes){let ack=client.apply(&p);if p.starts_with(b"IP"){held=Some(ack);original=p;}else{net.acknowledge(id,&ack).unwrap();}}if held.is_some(){break;}}
 for _ in 0..8{assert!(poll(&mut net,&f,10,2,&mut bytes).is_empty());if net.component_status(id).unwrap().unwrap().written_bytes==2{break;}}assert_eq!(bytes.len(),2);assert_eq!(net.acknowledge(id,&held.unwrap()).unwrap(),AckDisposition::DeferredUntilFrameEnd);capture(&mut w,e,&mut c,&mut f,&mut net,id);let mut actual=None;for _ in 0..3000{let packets=poll(&mut net,&f,10,64,&mut bytes);if let Some(packet)=packets.into_iter().next(){actual=Some(packet);break;}}assert_eq!(actual.unwrap(),original);assert_eq!(net.component_status(id).unwrap().unwrap().pending_bytes,0);assert_eq!(net.acknowledge(id,&held.unwrap()).unwrap(),AckDisposition::Duplicate);
}
#[test]
fn partial_disconnect_resume_and_new_stream_restore_definition_baseline(){
 let(mut w,e,mut c,mut f,mut net,id)=setup();capture(&mut w,e,&mut c,&mut f,&mut net,id);let mut client=Client::new(10);let mut bytes=Vec::new();for _ in 0..3000{for p in poll(&mut net,&f,0,64,&mut bytes){net.acknowledge(id,&client.apply(&p)).unwrap();}let status=net.component_status(id).unwrap().unwrap();if status.written_bytes>0{break;}}assert!(!bytes.is_empty());net.detach(id).unwrap();bytes.clear();net.resume(id).unwrap();let mut last=None;for _ in 0..3000{for p in poll(&mut net,&f,1,64,&mut bytes){let ack=client.apply(&p);if p.starts_with(b"IP"){last=Some(ack);}net.acknowledge(id,&ack).unwrap();}if drained(&net,id,&f){break;}}assert!(drained(&net,id,&f));net.detach(id).unwrap();let stream=net.reset_replica(id).unwrap();assert_eq!(net.acknowledge(id,&last.unwrap()),Err(NetworkError::Component(ComponentError::State(SyncError::WrongStream))));net.resume(id).unwrap();let mut fresh=Client::new(stream);for _ in 0..3000{for p in poll(&mut net,&f,2,64,&mut bytes){assert!(!p.starts_with(b"IC"));net.acknowledge(id,&fresh.apply(&p)).unwrap();}if fresh.components.sequence()>0&&drained(&net,id,&f){break;}}assert!(drained(&net,id,&f));assert_eq!(fresh.components.states(),client.components.states());assert_eq!(fresh.components.definition_count(),1);
}
#[test]
fn owner_change_premature_ack_and_timeout_do_not_silently_discard_pending_data(){
 let(mut w,e,mut c,mut f,mut net,id)=setup();assert_eq!(net.set_component_view(id,Some(e[1]),view()),Err(NetworkError::InvalidConfig));let ack=ComponentApplyReport{stream:10,sequence:1,tick:Tick(1),duplicate:false,version:2}.acknowledgement();assert_eq!(net.acknowledge(id,&ack),Err(NetworkError::Component(ComponentError::State(SyncError::OutOfOrder))));capture(&mut w,e,&mut c,&mut f,&mut net,id);let mut client=Client::new(10);let mut bytes=Vec::new();for _ in 0..3000{for p in poll(&mut net,&f,0,64,&mut bytes){let ack=client.apply(&p);if !p.starts_with(b"IP"){net.acknowledge(id,&ack).unwrap();}}if client.components.sequence()>0{break;}}let mut notices=Vec::new();net.poll_with_components(100,&f,&mut NetworkBudget{work:1,bytes:1},&mut notices,|_,_|panic!("timeout first")).unwrap();assert_eq!(notices[0].kind,NetworkNoticeKind::AckTimeout);assert!(!net.status(id).unwrap().attached);let retained=net.remove(id).unwrap();assert!(retained.components.unwrap().pending_packet().is_some());
}
#[test]
fn blocked_connection_does_not_starve_other_component_subscriptions(){
 let(mut w,e,mut c,mut f,mut net,blocked)=setup();let healthy=net.connect().unwrap();net.set_component_view(healthy,Some(e[1]),view()).unwrap();capture(&mut w,e,&mut c,&mut f,&mut net,blocked);let mut bytes=Vec::new();let mut replica=ComponentReplica::new_with_definitions(11);let mut notices=Vec::new();let mut complete=false;
 for _ in 0..1000{let mut budget=NetworkBudget{work:1,bytes:7};let r=net.poll_with_components(0,&f,&mut budget,&mut notices,|id,p|if id==blocked{WriteProgress::WouldBlock}else{bytes.extend_from_slice(p);WriteProgress::Written(p.len())}).unwrap();assert!(notices.is_empty());assert_eq!(budget.work+r.visited,1);assert_eq!(budget.bytes+r.bytes,7);if bytes.len()>=4{let len=u32::from_le_bytes(bytes[..4].try_into().unwrap())as usize;if bytes.len()==len+4{let report=replica.apply(&bytes[4..]).unwrap();net.acknowledge(healthy,&report.acknowledgement()).unwrap();complete=true;break;}}}
 assert!(complete);assert_eq!(replica.definition_count(),1);assert!(net.status(blocked).unwrap().attached);
}
